// EDUVERSE chunk: D — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_D = [{"bahas":"Jendela merupakan bagian dari rumah, sama seperti roda merupakan bagian dari mobil, sehingga keduanya menunjukkan hubungan bagian dengan keseluruhan. Pasangan penulis dengan buku menunjukkan hubungan pencipta dengan karya, kunci dengan pintu menunjukkan hubungan alat dengan benda yang dibukanya, air dengan gelas menunjukkan hubungan isi dengan wadah, dan meja dengan kayu menunjukkan hubungan benda dengan bahan pembuatnya.","id":"DPU01","kunci":2,"opsi":["Penulis : Buku","Kunci : Pintu","Roda : Mobil","Air : Gelas","Meja : Kayu"],"soal":"Jendela : Rumah = ... Pasangan kata manakah yang menunjukkan hubungan yang sama seperti pasangan kata tersebut?","subtes":"Penalaran Umum"},{"bahas":"Semua penabung aktif termasuk anggota koperasi, dan semua anggota koperasi menerima pembagian hasil usaha, sehingga semua penabung aktif juga menerima pembagian hasil usaha. Membalik hubungan antara anggota koperasi dan penabung aktif tidak mengikuti premis, pernyataan yang meniadakan atau membatasi penerimaan hasil usaha bertentangan dengan premis, dan tidak ada informasi yang memastikan adanya anggota koperasi yang bukan penabung aktif.","id":"DPU02","kunci":0,"opsi":["Semua penabung aktif menerima pembagian hasil usaha.","Semua anggota koperasi adalah penabung aktif.","Sebagian penabung aktif tidak menerima pembagian hasil usaha.","Tidak ada penabung aktif yang menerima pembagian hasil usaha.","Sebagian anggota koperasi bukan penabung aktif."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua anggota koperasi menerima pembagian hasil usaha. Premis 2: Semua penabung aktif adalah anggota koperasi. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Joko menempati posisi 5. Gita dan Hadi membentuk pasangan berurutan pada posisi 1 sampai 4, sedangkan Fajar harus berada di sebelah kiri Hadi. Susunan yang memenuhi semua syarat hanya Fajar-Gita-Hadi-Indah-Joko dan Fajar-Indah-Gita-Hadi-Joko. Pada semua susunan yang memenuhi syarat, Fajar selalu menempati posisi paling kiri, sedangkan posisi Gita, Hadi, dan Indah dapat berubah.","id":"DPU03","kunci":4,"opsi":["Gita berada di posisi kedua.","Indah berada tepat di sebelah kanan Hadi.","Hadi berada di posisi ketiga.","Gita berada di sebelah kiri Indah.","Fajar berada di stan paling kiri."],"soal":"Lima perajin, yaitu Fajar, Gita, Hadi, Indah, dan Joko, menempati stan pameran pada posisi 1 (paling kiri) sampai posisi 5 (paling kanan). Diketahui: Hadi berada tepat di sebelah kanan Gita; Fajar berada di sebelah kiri Hadi; Joko berada di stan paling kanan; Indah tidak berada di stan paling kiri. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Selisih antarbilangan yang berurutan adalah 2, 3, 5, 7, dan 11, yaitu bilangan prima yang berurutan. Bilangan prima berikutnya adalah 13, sehingga bilangan berikutnya adalah 31 ditambah 13, yaitu 44.","id":"DPU04","kunci":1,"opsi":["42","44","41","46","39"],"soal":"Perhatikan pola bilangan berikut: 3, 5, 8, 13, 20, 31, ... Bilangan berikutnya dalam pola tersebut adalah ...","subtes":"Penalaran Umum"},{"bahas":"Aturan kawasan mewajibkan setiap pengunjung yang memasuki kawasan didampingi pemandu dan memakai alas kaki tertutup. Sari memasuki kawasan tersebut, sehingga syarat tersebut berlaku untuk Sari. Keanggotaan kelompok, lama kunjungan, rencana kunjungan berikutnya, dan tempat lain yang dikunjungi Sari tidak dinyatakan dalam informasi yang diberikan.","id":"DPU05","kunci":3,"opsi":["Sari adalah anggota kelompok wisata yang baru dibentuk pada minggu ini.","Sari menghabiskan waktu lebih lama di kawasan itu daripada pengunjung lain.","Sari akan kembali mengunjungi kawasan itu pada minggu depan.","Sari didampingi pemandu dan memakai alas kaki tertutup.","Sari hari ini hanya mengunjungi kawasan konservasi dan tidak mengunjungi tempat lain."],"soal":"Di sebuah kawasan konservasi berlaku aturan: setiap pengunjung yang memasuki kawasan harus didampingi pemandu dan memakai alas kaki tertutup. Hari ini Sari memasuki kawasan konservasi tersebut. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Awal kalimat ditulis dengan huruf kapital, nama geografi Pantai Parangtritis ditulis dengan huruf kapital pada setiap unsurnya, dan nama hari Minggu ditulis dengan huruf kapital. Kalimat lain menulis awal kalimat, unsur nama geografi, atau nama hari dengan huruf kecil, atau menulis kata kerja di tengah kalimat dengan huruf kapital.","id":"DPPU01","kunci":4,"opsi":["mereka berwisata ke pantai parangtritis pada hari minggu.","Mereka berwisata ke Pantai parangtritis pada hari Minggu.","Mereka berwisata ke pantai Parangtritis pada hari minggu.","Mereka Berwisata ke Pantai Parangtritis pada hari minggu.","Mereka berwisata ke Pantai Parangtritis pada hari Minggu."],"soal":"Perhatikan kalimat-kalimat berikut. Kalimat manakah yang menggunakan huruf kapital dengan tepat menurut EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Musyawarah untuk mencapai mufakat merupakan ciri sila Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, yang menekankan pengambilan keputusan bersama melalui permusyawaratan. Sila lain menekankan ketuhanan, kemanusiaan, persatuan, dan keadilan sosial, bukan musyawarah sebagai cara mengambil keputusan.","id":"DPPU02","kunci":1,"opsi":["Ketuhanan Yang Maha Esa","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Keadilan sosial bagi seluruh rakyat Indonesia"],"soal":"Menyelesaikan perbedaan pendapat melalui musyawarah untuk mencapai mufakat merupakan pengamalan sila Pancasila yang berbunyi ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Danau Toba terletak di Provinsi Sumatera Utara dan terbentuk dari letusan gunung berapi. Provinsi lain yang disebutkan bukan letak Danau Toba: Aceh dan Sumatera Barat berada di Pulau Sumatera tetapi bukan letak danau tersebut, sedangkan Jawa Timur dan Kalimantan Selatan berada di pulau yang berbeda.","id":"DPPU03","kunci":3,"opsi":["Sumatera Barat","Aceh","Jawa Timur","Sumatera Utara","Kalimantan Selatan"],"soal":"Danau Toba, danau vulkanik terbesar di Indonesia, terletak di provinsi ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Gaya gravitasi adalah gaya tarik Bumi yang menarik benda ke arah permukaan Bumi, sehingga benda yang dilempar ke atas akan kembali jatuh. Gaya gesek menghambat gerak pada permukaan, gaya magnet bekerja pada benda yang dapat ditarik magnet, gaya otot berasal dari otot makhluk hidup, dan gaya pegas berasal dari benda elastis yang berubah bentuk.","id":"DPPU04","kunci":0,"opsi":["gaya gravitasi","gaya gesek","gaya magnet","gaya otot","gaya pegas"],"soal":"Benda yang dilempar ke atas akan kembali jatuh ke tanah karena pengaruh ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"id":"DPPU05","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Tari Kecak, tarian tradisional yang diiringi suara 'cak' yang diteriakkan beramai-ramai oleh para penari laki-laki, berasal dari daerah ...","opsi":["Sumatera Utara","Jawa Barat","Bali","Sulawesi Utara","Nusa Tenggara Timur"],"kunci":2,"bahas":"Tari Kecak berasal dari Bali dan dikenal dengan iringan suara 'cak' yang diteriakkan beramai-ramai oleh penari laki-laki yang duduk melingkar. Tarian ini berbeda dari tarian tradisional Sumatera Utara, Jawa Barat, Sulawesi Utara, dan Nusa Tenggara Timur."},{"bahas":"Bacaan menggambarkan koperasi yang membeli bahan bersama sehingga lebih murah, membagikan bahan secara adil, membuka toko bersama, dan mengadakan pelatihan, lalu pendapatan perajin menjadi lebih stabil dan pesanan datang dari luar desa. Rangkaian tersebut dirangkum dalam gagasan bahwa koperasi memperkuat usaha kecil perajin. Pembahasan tentang penjualan di desa saja bertentangan dengan isi bacaan, sedangkan pernyataan tentang harga bambu, pewarnaan alami, dan toko hanya mencakup sebagian isi bacaan atau menambahkan hal yang tidak dinyatakan.","id":"DPBM01","kunci":1,"opsi":["Perajin bambu sebaiknya menjual hasil karya hanya kepada pembeli yang datang ke desa.","Koperasi memperkuat usaha kecil perajin melalui pembelian bersama, pemasaran bersama, dan pelatihan.","Bambu yang dibeli dalam jumlah besar selalu lebih murah daripada bambu yang dibeli sedikit demi sedikit.","Pewarnaan alami adalah satu-satunya keterampilan yang dibutuhkan perajin anyaman bambu.","Toko di tepi jalan utama membuat semua perajin menjadi kaya dalam waktu singkat."],"soal":"Di sebuah desa, para perajin anyaman bambu bergabung dalam sebuah koperasi. Sebelum bergabung, mereka membeli bahan sendiri-sendiri dengan harga yang berbeda-beda dan menjual hasil karya hanya kepada pembeli yang datang ke desa. Setelah bergabung, koperasi membeli bambu dalam jumlah besar sehingga harganya lebih murah, lalu membagikan bahan itu kepada anggota secara adil. Koperasi juga membuka toko bersama di tepi jalan utama dan mengadakan pelatihan pewarnaan alami. Kini, pendapatan perajin menjadi lebih stabil dan pesanan datang dari luar desa. Koperasi itu menunjukkan bahwa kerja bersama dapat memperkuat usaha kecil. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Bacaan menyatakan warga dilatih dan membuka usaha di desa, hasil kunjungan dipakai memperbaiki jalan dan menanam pohon, kunjungan diawali penjelasan adat dan aturan kebersihan, serta jumlah rombongan dibatasi agar jalur tidak rusak. Hal itu menunjukkan wisata berbasis masyarakat memberi manfaat ekonomi sekaligus menjaga lingkungan dan adat. Bacaan tidak menyatakan seluruh warga muda kembali, tidak melarang pendakian, tidak membatasi pemakaian hasil kunjungan hanya untuk jalan, dan tidak membandingkan pentingnya pelatihan dengan kebersihan jalur.","id":"DPBM02","kunci":3,"opsi":["Semua warga muda yang pernah bekerja di kota kini kembali ke Desa Sukamaju.","Wisatawan tidak lagi diizinkan mendaki jalur bukit karena jalur tersebut sudah rusak.","Hasil kunjungan wisata hanya digunakan untuk memperbaiki jalan desa dan tidak untuk keperluan lain.","Wisata berbasis masyarakat memberi manfaat ekonomi bagi warga sekaligus menjaga lingkungan dan adat desa.","Pelatihan pemandu dan pengelola homestay lebih penting daripada menjaga kebersihan jalur pendakian."],"soal":"Desa Sukamaju mulai mengembangkan wisata berbasis masyarakat tiga tahun lalu. Warga dilatih menjadi pemandu, pengelola homestay, dan penyaji kuliner khas. Setiap kunjungan diawali dengan penjelasan tentang adat setempat dan aturan menjaga kebersihan jalur pendakian. Sebagian hasil kunjungan disisihkan untuk memperbaiki jalan desa dan menanam pohon di lereng bukit. Jumlah wisatawan meningkat dari tahun ke tahun, tetapi desa membatasi jumlah rombongan setiap hari agar jalur tidak rusak. Kini, cukup banyak warga muda yang sebelumnya bekerja di kota kembali membuka usaha di desa mereka sendiri secara mandiri. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, listrik dari panel surya dipakai untuk lampu belajar dan pertemuan warga sehingga kegiatan belajar malam hari dapat berjalan. Makna tersebut sesuai dengan mendukung berlangsungnya kegiatan dengan menyediakan kebutuhan dasarnya. Makna mengganti kegiatan, menahan kegiatan, memindahkan kegiatan, atau membatasi kegiatan tidak sesuai dengan isi bacaan.","id":"DPBM03","kunci":0,"opsi":["mendukung berlangsungnya kegiatan dengan menyediakan kebutuhan dasarnya","menggantikan seluruh kegiatan belajar dengan kegiatan lain yang sepenuhnya baru","menahan kegiatan belajar agar tidak berjalan terlalu lama","memindahkan kegiatan belajar ke tempat lain yang lebih terang","membatasi kegiatan belajar hanya pada malam hari saja"],"soal":"Sebuah dusun terpencil di lereng gunung kini mendapat listrik dari panel surya yang dipasang di atap balai dusun. Sebelumnya, warga hanya mengandalkan lampu minyak yang redup dan mahal bahan bakarnya. Panel surya mengisi baterai pada siang hari, lalu listriknya dipakai pada malam hari untuk lampu belajar, kipas pendingin, dan pengeras suara saat pertemuan warga. Perawatan panel dilakukan oleh dua warga yang dilatih secara khusus, dan biaya perawatannya ditanggung bersama melalui iuran kecil. Listrik dari panel surya menopang kegiatan belajar anak-anak pada malam hari dan membuat pertemuan warga berjalan lebih tertib. Kata 'menopang' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata kegiatan, menggabungkan penanda sangat dan sekali, serta mengulang gagasan menambah penghasilan. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan yang jelas, tanpa pengulangan kata dan tanpa penanda penguat ganda: kegiatan ini bermanfaat karena menambah penghasilan keluarga ibu-ibu. Susunan lain masih mempertahankan pengulangan kata kegiatan, penguat ganda, atau pengulangan gagasan menambah penghasilan sehingga tetap bertele-tele.","id":"DPBM04","kunci":4,"opsi":["Kegiatan ini adalah kegiatan yang sangat bermanfaat sekali karena kegiatan ini menambah penghasilan ibu-ibu yang menambah penghasilan keluarga mereka.","Kegiatan yang sangat bermanfaat sekali ini adalah kegiatan yang bermanfaat untuk menambah penghasilan ibu-ibu dan keluarga mereka.","Kegiatan ini membuat ibu-ibu menjadi bertambah penghasilannya yang sangat bermanfaat sekali bagi penghasilan keluarga mereka.","Kegiatan ini adalah kegiatan yang bermanfaat karena ibu-ibu menambah penghasilan yang menambah penghasilan keluarga mereka.","Kegiatan ini bermanfaat karena menambah penghasilan keluarga ibu-ibu."],"soal":"Kelompok ibu-ibu di Dusun Kenanga membuat sabun dari minyak kelapa dan rempah. Mereka mencampur bahan di dapur bersama setiap hari Sabtu, mencetak sabun dalam cetakan kayu, lalu mengeringkannya selama dua minggu sebelum dikemas. Kemasan sabun memakai kertas daur ulang yang dihias cap daun, sehingga tampilannya sederhana tetapi menarik. Sabun yang sudah dikemas dijual di pasar desa dan dititipkan di beberapa warung tetangga. Kegiatan ini adalah kegiatan yang sangat bermanfaat sekali karena kegiatan ini sangat bermanfaat untuk menambah penghasilan ibu-ibu yang menambah penghasilan keluarga mereka. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Awalan di pada kata kerja pasif ditulis serangkai dengan kata dasarnya sehingga bentuk yang tepat adalah diikuti. Nama desa ditulis dengan huruf kapital pada setiap unsurnya sehingga bentuk yang tepat adalah Desa Sari, Desa Rejo, dan Desa Makmur. Tanda koma dipakai sebelum kata dan pada pemerincian tiga unsur sehingga bentuk yang tepat memakai koma sebelum dan pada unsur terakhir. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan diikuti, nama desa yang memakai huruf kapital, dan pemerincian yang memakai koma sebelum dan.","id":"DPBM05","kunci":2,"opsi":["Pelatihan itu di ikuti oleh warga dari Desa Sari, Desa Rejo, dan Desa Makmur.","Pelatihan itu diikuti oleh warga dari desa Sari, desa Rejo, dan desa Makmur.","Pelatihan itu diikuti oleh warga dari Desa Sari, Desa Rejo, dan Desa Makmur.","Pelatihan itu diikuti oleh warga dari Desa Sari, Desa Rejo dan Desa Makmur.","Pelatihan itu di ikuti oleh warga dari desa Sari, desa Rejo dan desa Makmur."],"soal":"(1) Kelompok pemuda Desa Cempaka mengadakan pelatihan pembuatan kompos dari sampah dapur untuk warga sekitar setiap bulan. (2) Pelatihan ini bertujuan mengurangi sampah yang dibuang ke sungai dan menghasilkan pupuk alami untuk kebun warga. (3) Pelatihan itu di ikuti oleh warga dari desa Sari, desa Rejo dan desa Makmur. (4) Peserta belajar bersama-sama memilah sampah organik, mencampur bahan dengan daun kering, dan menjaga kelembapan tumpukan kompos. (5) Kompos yang sudah jadi dibagikan kepada setiap peserta agar dapat segera dipakai di kebun rumah masing-masing dan mengurangi pembelian pupuk kimia. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"id":"DPK01","subtes":"Pengetahuan Kuantitatif","soal":"Harga sebuah lampu meja adalah Rp200.000. Toko menaikkan harga tersebut sebesar 10%, kemudian memberikan potongan 20% dari harga setelah kenaikan. Berapa harga akhir lampu meja itu?","opsi":["Rp160.000","Rp168.000","Rp180.000","Rp176.000","Rp184.000"],"kunci":3,"bahas":"Kenaikan 10% dari Rp200.000 adalah Rp20.000 sehingga harga setelah kenaikan menjadi Rp220.000. Potongan 20% dihitung dari Rp220.000, yaitu Rp44.000, sehingga harga akhir menjadi Rp220.000 dikurangi Rp44.000, yaitu Rp176.000. Potongan tidak dihitung dari harga awal."},{"id":"DPK02","subtes":"Pengetahuan Kuantitatif","soal":"Perbandingan banyak cat merah dan cat putih yang dipakai untuk mengecat sebuah balai adalah 3:5. Selisih banyak cat merah dan cat putih adalah 24 liter. Berapa jumlah cat merah dan cat putih yang dipakai?","opsi":["96 liter","84 liter","108 liter","72 liter","120 liter"],"kunci":0,"bahas":"Selisih perbandingan adalah 5 dikurangi 3, yaitu 2 bagian, dan selisih tersebut setara dengan 24 liter sehingga satu bagian setara dengan 12 liter. Jumlah perbandingan adalah 3 ditambah 5, yaitu 8 bagian, sehingga jumlah cat adalah 8 dikali 12 liter, yaitu 96 liter."},{"id":"DPK03","subtes":"Pengetahuan Kuantitatif","soal":"Perhatikan barisan bilangan berikut: 3, 5, 9, 17, 33, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["61","63","65","67","69"],"kunci":2,"bahas":"Setiap suku sama dengan dua pangkat bilangan berurutan ditambah 1: 2 pangkat 1 ditambah 1 sama dengan 3, 2 pangkat 2 ditambah 1 sama dengan 5, 2 pangkat 3 ditambah 1 sama dengan 9, 2 pangkat 4 ditambah 1 sama dengan 17, dan 2 pangkat 5 ditambah 1 sama dengan 33. Suku berikutnya adalah 2 pangkat 6 ditambah 1, yaitu 65."},{"bahas":"Misalkan lebar papan reklame adalah l m sehingga panjangnya adalah 3l m. Keliling sama dengan 2 dikali jumlah panjang dan lebar sehingga 2 dikali 4l sama dengan 48. Dari persamaan tersebut diperoleh 4l sama dengan 24, sehingga l sama dengan 6. Panjangnya adalah 18 m dan luasnya adalah 18 dikali 6, yaitu 108 m².","id":"DPK04","kunci":4,"opsi":["96 m²","120 m²","84 m²","144 m²","108 m²"],"soal":"Panjang sebuah papan reklame berbentuk persegi panjang adalah 3 kali lebarnya. Jika keliling papan reklame tersebut adalah 48 m, berapa luasnya?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Jumlah hasil panen selama empat minggu adalah 36 + 42 + 39 + 47 = 164 kg. Rata-rata hasil panen per minggu diperoleh dengan membagi 164 kg dengan 4, yaitu 41 kg.","id":"DPK05","kunci":1,"opsi":["40 kg","41 kg","42 kg","39 kg","43 kg"],"soal":"Hasil panen cabai sebuah kelompok tani selama empat minggu berturut-turut adalah 36 kg, 42 kg, 39 kg, dan 47 kg. Berapa rata-rata hasil panen cabai per minggu?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Teks membahas warga yang memilah dan menyetorkan sampah, petugas yang menimbang dan mencatat setoran, hasil penjualan sampah yang menjadi tabungan warga, lingkungan yang menjadi lebih bersih, penghasilan tambahan, dan anak-anak yang belajar bahwa sampah yang dikelola masih memiliki nilai. Gagasan utamanya mencakup manfaat lingkungan, manfaat ekonomi, dan pembelajaran tersebut, bukan hanya satu rincian, hal yang tidak dinyatakan teks, atau cara mengatasi sampah yang dinyatakan sebagai satu-satunya cara.","id":"DLBI01","kunci":0,"opsi":["Bank sampah membuat lingkungan lebih bersih, memberi penghasilan tambahan, dan mengajarkan nilai sampah yang dikelola.","Setiap rumah wajib menyerahkan sampah plastik, kertas, dan kaleng pada jadwal yang ditentukan.","Pengepul membeli semua sampah warga dengan harga yang sama setiap minggu.","Anak-anak di lingkungan padat belum memahami cara memilah sampah dengan benar.","Tumpukan sampah yang bercampur hanya dapat diatasi dengan mendirikan bank sampah."],"soal":"Di sebuah lingkungan padat, warga mendirikan bank sampah untuk mengatasi tumpukan sampah yang bercampur. Setiap rumah memilah sampah plastik, kertas, dan kaleng, lalu menyerahkannya pada jadwal yang ditentukan. Petugas bank sampah menimbang setoran warga dan mencatat nilainya dalam buku tabungan. Sampah yang terkumpul dijual kepada pengepul, dan hasilnya dibagikan sebagai tabungan warga. Selain lingkungan menjadi lebih bersih, warga memperoleh penghasilan tambahan dari barang yang semula dibuang. Kegiatan ini juga membuat anak-anak belajar bahwa sampah yang dikelola dengan baik masih memiliki nilai. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan kunjungan diawali penjelasan makna motif, wisatawan menggambar pola lalu memakai canting dengan bimbingan perajin, garis yang salah sulit diperbaiki, wisatawan membawa pulang kain hasil karyanya, dan jumlah peserta dibatasi agar bimbingan cukup. Pernyataan yang sesuai merangkum tahapan belajar dengan bimbingan dan hasil karya yang dibawa pulang. Pernyataan lain bertentangan dengan teks karena menyatakan tidak ada kesalahan, perajin menggambar seluruh pola, peserta tidak dibatasi, atau penjelasan makna motif hanya untuk wisatawan yang sudah mahir.","id":"DLBI02","kunci":2,"opsi":["Semua wisatawan berhasil membuat batik tanpa kesalahan pada percobaan pertama.","Perajin menggambar seluruh pola batik untuk wisatawan agar hasilnya selalu rapi.","Wisatawan belajar membatik tahap demi tahap dengan bimbingan perajin dan membawa pulang hasil karyanya.","Jumlah peserta setiap sesi tidak dibatasi agar suasana belajar menjadi lebih ramai.","Makna motif batik hanya dijelaskan kepada wisatawan yang sudah mahir menggambar pola."],"soal":"Di sebuah desa, wisatawan dapat belajar membatik langsung dari para perajin. Kunjungan diawali dengan penjelasan tentang makna motif, lalu wisatawan mencoba menggambar pola dengan pensil di atas kain. Setelah itu, mereka belajar memakai canting untuk menorehkan malam panas dengan bimbingan perajin. Proses ini membutuhkan kesabaran karena garis yang salah sulit diperbaiki. Di akhir kunjungan, wisatawan membawa pulang kain batik hasil karyanya sendiri sebagai kenang-kenangan. Pengelola membatasi jumlah peserta setiap sesi agar setiap wisatawan mendapat bimbingan yang cukup dan suasana belajar tetap tenang. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan Bu Sari yang menawarkan potongan harga kecil bagi pembeli yang membawa wadah sendiri, keraguan awal sebagian pembeli, bertambahnya pembeli yang membawa wadah, dan berkurangnya tumpukan sampah tanpa mengubah menu atau menaikkan harga. Kisah tersebut berfungsi sebagai contoh bahwa perubahan satu kebiasaan kecil di usaha kecil dapat mengurangi sampah secara nyata, bukan sebagai ajakan umum, penjelasan menu, perbandingan keuntungan, atau anjuran menaikkan harga.","id":"DLBI03","kunci":4,"opsi":["Menunjukkan bahwa semua warung makan wajib menaikkan harga agar sampahnya berkurang.","Menjelaskan daftar menu dan jam ramai warung makan milik Bu Sari secara rinci.","Mengajak semua pembeli membawa wadah sendiri setiap kali membeli makanan di mana pun.","Membandingkan keuntungan warung yang memakai wadah sekali pakai dengan warung yang tidak memakainya.","Menunjukkan bahwa perubahan satu kebiasaan kecil di usaha kecil dapat mengurangi sampah secara nyata."],"soal":"Warung makan milik Bu Sari selalu ramai pada jam makan siang. Dahulu, setiap pembeli yang membawa pulang makanan menerima kantong dan wadah sekali pakai. Suatu hari, Bu Sari menawarkan potongan harga kecil bagi pembeli yang membawa wadah sendiri. Awalnya hanya beberapa pembeli yang mencoba, dan sebagian merasa repot membawa wadah dari rumah. Namun, setelah beberapa bulan, semakin banyak pembeli yang datang dengan wadah sendiri, dan tumpukan sampah di belakang warung berkurang dengan jelas. Bu Sari tidak mengubah menu atau menaikkan harga; ia hanya mengubah satu kebiasaan kecil di warungnya. Apa tujuan penulis menyajikan kisah Bu Sari dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Pak Darma membiarkan para pemuda mencoba sendiri, tidak mengambil alih pekerjaan mereka, dan mengulang gerakannya perlahan, lalu setelah berbulan-bulan mencoba beberapa pemuda menghasilkan gerabah yang rapi dan tungku tidak lagi menyala hanya untuk Pak Darma. Rangkaian peristiwa tersebut menyiratkan bahwa keterampilan tradisional dapat bertahan bila pewarisnya diberi kesempatan mencoba dan belajar dengan sabar. Pernyataan lain bertentangan dengan teks, menafsirkan kiasan secara harfiah, atau menambahkan hal yang tidak dinyatakan teks.","id":"DLBI04","kunci":1,"opsi":["Gerabah yang rapi hanya dapat dibuat oleh perajin yang sudah berusia lanjut.","Keterampilan tradisional dapat bertahan bila pewarisnya diberi kesempatan mencoba dan belajar dengan sabar.","Tanah liat harus dikenal selama berbulan-bulan sebelum boleh dibentuk menjadi apa pun.","Pak Darma tidak lagi membuat gerabah sendiri karena tungkunya dipakai para pemuda.","Semua pemuda desa kini menjadi perajin gerabah yang lebih terampil daripada Pak Darma."],"soal":"Setiap sore, Pak Darma duduk di depan tungku gerabahnya sambil membentuk tanah liat menjadi kendi dan mangkuk. Para pemuda desa sering datang untuk menonton, dan Pak Darma membiarkan mereka mencoba memutar roda gerabah sendiri. Hasil pertama mereka selalu miring, retak, atau terlalu tipis, tetapi Pak Darma tidak pernah mengambil alih pekerjaan itu. Ia hanya mengulang gerakan tangannya perlahan dan berkata bahwa tanah liat perlu dikenal sebelum dibentuk. Setelah berbulan-bulan datang dan mencoba, beberapa pemuda mulai menghasilkan gerabah yang rapi. Kini, tungku itu tidak lagi menyala hanya untuk Pak Darma seorang. Apa makna tersirat dari tindakan Pak Darma dan perubahan para pemuda dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat penolak mengabaikan cara kerja sistem panel surya, lalu menjelaskan panel surya mengisi baterai pada siang hari untuk dipakai malam hari dan sebagian kebutuhan listrik juga terjadi pada siang hari. Kelemahannya terletak pada cara menilai panel surya tanpa mempertimbangkan penyimpanan energi dan pola pemakaian listrik warga sepanjang hari. Pernyataan lain menyatakan fakta sanggahan sebagai kelemahan, membandingkan kebutuhan siang dan malam yang tidak dibandingkan teks, atau menambahkan hal yang tidak dinyatakan teks.","id":"DLBI05","kunci":3,"opsi":["anggapan bahwa panel surya dapat menyimpan energi dalam baterai untuk dipakai malam hari","keyakinan bahwa warga dusun terpencil membutuhkan listrik sepanjang hari tanpa henti","gagasan bahwa kebutuhan listrik pada siang hari lebih besar daripada kebutuhan pada malam hari","penilaian yang mengabaikan penyimpanan energi dan pola pemakaian listrik warga sepanjang hari","dugaan bahwa semua warga dusun terpencil menolak pemasangan panel surya di dusun mereka"],"soal":"Sebagian orang berpendapat bahwa panel surya tidak berguna bagi dusun terpencil karena matahari tidak bersinar pada malam hari, saat warga paling membutuhkan listrik. Pendapat ini mengabaikan cara kerja sistem panel surya yang sebenarnya. Panel surya mengisi baterai pada siang hari, dan energi yang tersimpan dipakai pada malam hari untuk lampu dan peralatan kecil. Selain itu, sebagian kebutuhan listrik warga, seperti mengisi daya telepon dan menjalankan kipas, juga terjadi pada siang hari. Menilai panel surya hanya dari ada tidaknya sinar matahari pada malam hari adalah cara menilai yang tidak lengkap, karena mengabaikan penyimpanan energi dan pola pemakaian warga sepanjang hari. Menurut teks, kelemahan pendapat yang menolak panel surya terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan keluarga yang bergiliran menerima tamu, tamu yang ikut melaut, memperbaiki jaring, dan memasak bersama, sebagian penghasilan yang dipakai memperbaiki perahu dan menjaga kebersihan pantai, serta warga yang memperoleh penghasilan tambahan tanpa meninggalkan kampung halaman. Gagasan utama mencakup seluruh hal tersebut: wisata yang dikelola masyarakat membantu desa memperoleh penghasilan sambil menjaga kehidupan sehari-hari dan lingkungannya, bukan hanya satu rincian atau perbandingan yang tidak dinyatakan teks.","id":"DLBE01","kunci":2,"opsi":["Fishing villages should stop welcoming visitors so that fishermen can focus only on catching fish.","Mending nets and cooking the catch are the most difficult jobs in a fishing village.","Community-managed tourism helps a fishing village earn income while keeping its daily life and environment in good shape.","All visitors to the village must join fishermen early in the morning without exception.","Repairing boats is more important than keeping the beach clean for village residents."],"soal":"In a small fishing village, families opened their homes to visitors who wanted to learn about daily life by the sea. Guests join fishermen early in the morning, help mend nets, and cook the catch together with their hosts. The families take turns welcoming visitors so that no single household carries all the work. Part of the income is used to repair boats and keep the beach clean. Visitors leave with a better understanding of the village, and residents earn extra income without leaving their home. The program shows that tourism can support a community when residents themselves plan and manage it. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Kata tersebut menggambarkan pekerjaan Wulan yang diawali penjelasan bahwa setiap kain membutuhkan beberapa hari, satu kesalahan dapat memaksanya mengulang pekerjaan berjam-jam, dan dilanjutkan rincian jam kerja yang panjang, tangan yang hati-hati, dan perhatian yang terus-menerus terhadap warna dan benang. Gambaran tersebut menunjukkan pekerjaan yang membutuhkan banyak usaha dan perhatian, bukan pekerjaan yang santai, membosankan, berbahaya, atau cepat dan sederhana.","id":"DLBE02","kunci":4,"opsi":["relaxing and effortless","boring and repetitive","dangerous and frightening","quick and simple","requiring a lot of effort and attention"],"soal":"When Wulan opened a small weaving workshop in her village, she knew the work would be slow. Each cloth takes several days to finish, and a single mistake in the pattern can force her to undo hours of work. The work was demanding: long hours at the loom, careful hands, and constant attention to color and thread. Wulan, however, enjoys the quiet rhythm of the loom and the moment a finished cloth is lifted from the frame. She sells her cloth at the village market and teaches two neighbors the basic steps. Her workshop is small, but it gives her a steady income and a craft she is proud to keep alive. The word 'demanding' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan lebih dari separuh pelanggan tetap beralih ke isi ulang dalam tiga bulan, toko memesan botol plastik lebih sedikit setiap minggu, sekolah meminta penjelasan tentang sistem tersebut, dan pemilik toko berencana menambah wadah isi ulang untuk minyak goreng dan cairan pencuci piring. Rangkaian fakta tersebut menunjukkan pelanggan menerima sistem isi ulang sehingga pemilik toko memperluasnya ke produk lain. Teks tidak menyatakan seluruh pelanggan berhenti membeli kemasan plastik, pemilik toko memaksa pelanggan, siswa menjalankan sistem, atau harga isi ulang yang selalu lebih murah.","id":"DLBE03","kunci":1,"opsi":["All customers in the neighborhood have stopped buying products in plastic bottles completely.","Customers accepted the refill system, encouraging the owner to expand it to other products.","The shop owner forced regular customers to switch to refills within three months.","Students at the nearby school now run the refill system for the shop owner.","Refill products are always cheaper than packaged products in every shop."],"soal":"A small shop in a busy neighborhood began selling soap and detergent from large refill containers. Customers bring their own bottles, pay only for the amount they take, and return when the bottle is empty. At first, the owner worried that people would find the new system troublesome. Within three months, however, more than half of the shop's regular customers had switched to refills, and the shop ordered fewer plastic bottles each week. A school nearby even asked the owner to explain the system to students. The owner now plans to add refill containers for cooking oil and dishwashing liquid. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan pembeli membayar harga yang lebih baik karena kualitas biji yang dikeringkan lebih merata setelah petani memakai tempat penjemuran bersama dengan alas yang ditinggikan dan giliran memeriksa cuaca serta membalik biji. Pencatatan waktu penjemuran, penghematan waktu, cara penjemuran lama di tepi jalan, dan harga tetap yang ditetapkan koperasi bukan alasan harga yang dinyatakan teks.","id":"DLBE04","kunci":3,"opsi":["Because the cooperative keeps records of drying time for every batch of beans.","Because farmers dry their beans on mats beside the road near the village.","Because the shared yard saves farmers time when they sell their harvest.","Because the beans have more even quality after being dried in the shared yard.","Because buyers are required to pay a fixed price set by the cooperative."],"soal":"A cooperative of coffee farmers in a highland village built a shared drying yard for their harvest. Before the yard existed, each farmer dried beans on mats beside the road, where dust and sudden rain often spoiled part of the crop. Now farmers bring their beans to the yard, spread them on raised beds, and take turns checking the weather and turning the beans. The cooperative also keeps records of drying time for each batch. Buyers pay a better price for the dried beans because the quality is more even. Farmers say the shared yard saves time and gives them greater confidence when selling their harvest. According to the passage, why do buyers pay a better price for the cooperative's dried beans?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Dani yang menemukan sepeda tua kakeknya, membersihkan dan memperbaiki setiap bagian bersama kakeknya pada sore hari yang santai, belajar mengenali setiap bagian, dan akhirnya memakai sepeda itu ke sekolah sambil memandangnya sebagai hasil kerja bersama. Cerita tersebut menggambarkan nilai kerja langsung yang sabar bersama kerabat yang lebih tua dalam memberi makna baru pada benda lama, bukan kecepatan memperbaiki, keharusan memperbaiki, pemulihan yang sempurna, atau cara memilih suku cadang.","id":"DLBE05","kunci":0,"opsi":["To show that patient, hands-on work with an older relative can give an old object new meaning.","To argue that teenagers repair bicycles faster than older people in every case.","To suggest that old bicycles should always be repaired instead of replaced.","To prove that anyone can restore a bicycle completely within two months.","To explain the best method for choosing replacement parts for an old bicycle."],"soal":"At fifteen, Dani found his grandfather's old bicycle rusting behind the house. The chain was stiff, the tires were flat, and the paint had peeled in several places. His grandfather did not buy new parts right away. Instead, they cleaned each piece together, oiled the chain, and patched the tires on slow Sunday afternoons. Dani learned to name every part and to listen for the sound of a wheel turning smoothly. After two months, the bicycle carried him to school again. He still checks the brakes every morning, but he no longer sees the bicycle as an old machine. He sees it as something he and his grandfather rebuilt together. What is the author's purpose in telling Dani's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 6 hari, 4 anggota membuat 96 keranjang, sehingga satu anggota membuat 24 keranjang dalam 6 hari atau 4 keranjang dalam 1 hari. Untuk 6 anggota selama 8 hari: 6 x 8 x 4 = 192 keranjang.","id":"DPM01","kunci":1,"opsi":["180","192","168","204","216"],"soal":"Sebuah kelompok perajin memiliki 4 anggota yang bekerja dengan laju sama. Keempat anggota tersebut membuat 96 keranjang anyaman dalam 6 hari. Jika kelompok itu menambah anggota menjadi 6 orang dan semuanya bekerja selama 8 hari dengan laju yang sama, berapa keranjang anyaman yang dihasilkan?","subtes":"Penalaran Matematika"},{"id":"DPM02","subtes":"Penalaran Matematika","soal":"Perhatikan barisan bilangan berikut: 8, 24, 12, 36, 18, ... Bilangan berikutnya dalam barisan tersebut adalah ....","opsi":["48","50","52","54","56"],"kunci":3,"bahas":"Pola bergantian mengalikan 3 lalu membagi 2: 8 dikali 3 sama dengan 24, 24 dibagi 2 sama dengan 12, 12 dikali 3 sama dengan 36, dan 36 dibagi 2 sama dengan 18. Langkah berikutnya adalah mengalikan 3, sehingga bilangan berikutnya adalah 18 dikali 3, yaitu 54."},{"bahas":"Jumlah berat 5 kotak semula adalah 5 dikali 12 kg, yaitu 60 kg. Setelah ditambah satu kotak seberat 21 kg, jumlah berat menjadi 81 kg. Rata-rata berat 6 kotak adalah 81 kg dibagi 6, yaitu 13,5 kg.","id":"DPM03","kunci":0,"opsi":["13,5 kg","13 kg","14 kg","12,5 kg","15 kg"],"soal":"Rata-rata berat 5 kotak kerajinan adalah 12 kg. Jika ditambah satu kotak kerajinan seberat 21 kg, berapa rata-rata berat 6 kotak kerajinan tersebut?","subtes":"Penalaran Matematika"},{"bahas":"Seluruh hasil yang mungkin ada 6 dikali 6, yaitu 36 hasil yang sama kemungkinannya. Hasil yang jumlah mata dadunya 9 ada 4, yaitu pasangan 3 dan 6, 4 dan 5, 5 dan 4, serta 6 dan 3. Peluangnya adalah 4/36, yaitu 1/9.","id":"DPM04","kunci":2,"opsi":["1/6","1/12","1/9","1/8","5/36"],"soal":"Dua buah dadu bersisi enam yang adil dilantunkan bersama-sama satu kali. Peluang bahwa jumlah mata dadu yang muncul sama dengan 9 adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Banyak anggota yang berprofesi sebagai perajin adalah 35% dari 240, yaitu 84 anggota. Banyak anggota yang berprofesi sebagai petani adalah 240 dikurangi 84, yaitu 156 anggota. Cara lain: persentase petani adalah 100% dikurangi 35%, yaitu 65%, dan 65% dari 240 adalah 156.","id":"DPM05","kunci":4,"opsi":["84","96","120","144","156"],"soal":"Sebuah koperasi memiliki 240 anggota. Sebanyak 35% anggota adalah perajin, dan sisanya adalah petani. Berapa banyak anggota koperasi yang berprofesi sebagai petani?","subtes":"Penalaran Matematika"}];
